// Extract latest versions search parameters
const query = $input.item.json.query;
const limit = $input.item.json.limit || 10;
const minScore = $input.item.json.min_score || 0.7;
const conversationId = $input.item.json.conversation_id;

if (!query) {
  throw new Error('query is required');
}

return {
  query,
  limit,
  minScore,
  conversationId,
  timestamp: new Date().toISOString()
};

// Format latest versions search results for MS Teams
const results = $input.item.json.results || [];
const metadata = $input.item.json.metadata || {};

let message = `**📑 Latest Document Versions**\n\n`;
message += `Query: "${metadata.query || 'N/A'}"\n`;
message += `Total Results: ${metadata.total_results || 0}\n`;
if (metadata.version_filter_applied) {
  message += `✅ Filter: Latest versions only\n`;
}
message += '\n';

if (results.length === 0) {
  message += '⚠️ No matching documents found.\n\n';
  message += 'Note: Only the latest version of each document is included in results.\n';
} else {
  results.forEach((result, index) => {
    message += `**${index + 1}. ${result.file_name || 'Unknown'}**\n`;
    message += `📄 Score: ${(result.score || 0).toFixed(3)}\n`;

    if (result.version) {
      message += `📌 Version: ${result.version}\n`;
    }
    if (result.document_date) {
      message += `📅 Date: ${result.document_date}\n`;
    }
    if (result.document_type) {
      message += `📑 Type: ${result.document_type}\n`;
    }

    if (result.text) {
      const preview = result.text.substring(0, 130);
      message += `\n${preview}${result.text.length > 130 ? '...' : ''}\n`;
    }

    message += '\n---\n\n';
  });

  message += '💡 Tip: Use `/search` for historical versions.\n';
}

return {
  message,
  conversation_id: $input.item.json.conversation_id
};

// Return formatted response
return {
  json: {
    success: true,
    message: $json.message,
    conversation_id: $json.conversation_id
  }
};
